    pub fn generate_and_execute_batch<I>(&self, paths: I, buffer_output: bool) -> ExitCode
    where
        I: Iterator<Item = PathBuf>,
    {
        let mut paths: Vec<_> = paths.collect();
        paths.sort();

        let executable = self.args[0].generate("", None);
        let max_arg_length = max_command_length();

        // Pre-compute the length contribution of the fixed (non-placeholder) arguments, and
        // the length of the executable itself, so we know how much room is left for paths.
        let mut base_length = executable.len() + 1;
        for arg in &self.args[1..] {
            if !arg.has_tokens() {
                base_length += arg.generate("", None).len() + 1;
            }
        }

        let mut paths = paths.iter().peekable();
        let mut results = Vec::new();
        let mut has_path = false;

        while paths.peek().is_some() {
            let mut cmd = Command::new(&executable);
            cmd.stdin(Stdio::inherit());
            cmd.stdout(Stdio::inherit());
            cmd.stderr(Stdio::inherit());

            let mut current_length = base_length;
            let mut batch_has_path = false;

            for arg in &self.args[1..] {
                if arg.has_tokens() {
                    // A single `Tokens` argument is expected, so we can directly consume the
                    // iterator here, adding as many paths as fit within the maximum command
                    // length supported by the current platform.
                    while let Some(path) = paths.peek() {
                        let generated =
                            arg.generate(strip_current_dir(path), self.path_separator.as_deref());
                        let length = generated.len() + 1;

                        if batch_has_path && current_length + length > max_arg_length {
                            break;
                        }

                        cmd.arg(generated);
                        current_length += length;
                        batch_has_path = true;
                        has_path = true;

                        paths.next();
                    }
                } else {
                    cmd.arg(arg.generate("", None));
                }
            }

            if batch_has_path {
                results.push(execute_command(cmd, &Mutex::new(()), buffer_output));
            } else {
                // The remaining path(s) don't fit within the maximum command length, even on
                // their own. Bail out to avoid looping forever.
                break;
            }
        }

        if has_path {
            merge_exitcodes(results)
        } else {
            ExitCode::Success
        }
    }
}

/// Determine the maximum length (in bytes) of the arguments that can be passed to a new
/// process, leaving some room for the executable name and the environment.
#[cfg(unix)]
fn max_command_length() -> usize {
    // Reserve a decent amount of space for the environment (and some general overhead), since
    // it counts against the same limit on most platforms.
    const RESERVE: usize = 4096;

    let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
    let arg_max = if arg_max > 0 { arg_max as usize } else { 0 };

    // Fall back to a conservative default if the value couldn't be determined.
    let arg_max = if arg_max == 0 { 128 * 1024 } else { arg_max };

    let env_size: usize = std::env::vars_os()
        .map(|(key, value)| key.len() + value.len() + 2)
        .sum();

    arg_max
        .saturating_sub(env_size)
        .saturating_sub(RESERVE)
        .max(4096)
}

/// Determine the maximum length (in bytes) of the arguments that can be passed to a new
/// process. There is no easy way to query this on non-Unix platforms, so a conservative
/// constant is used instead.
#[cfg(not(unix))]
fn max_command_length() -> usize {
    32 * 1024
}

